import clsx from 'clsx';
import React, { forwardRef } from 'react';

import { dividerCSS } from './Divider.sty.js';
import type { DataTestId } from '../core/types/data-props.js';
import type { StylingProps } from '../core/types/styling-props.js';

// #region Typings
/** Orientation options for the direction of the divider.
 * @deprecated Will be removed.
 */
export const dividerOrientationOptions = ['horizontal', 'vertical'] as const;

/** @deprecated Will be removed. */
export type DividerOrientation = (typeof dividerOrientationOptions)[number];

/**
 * Rendering options for the Divider HTML-tag
 * @deprecated Will be removed.
 */
export type DividerTag = 'hr' | 'div';

/** @deprecated Will be removed. */
export type DividerColor =
  | 'primary'
  | 'neutral'
  | 'success'
  | 'warning'
  | 'critical';

/** @deprecated Will be removed. */
export type DividerVariant = 'default' | 'accent';

export interface DividerProps extends StylingProps, DataTestId {
  /**
   * Orientation of the Divider component.
   * @defaultValue 'horizontal'
   */
  orientation?: 'horizontal' | 'vertical';
  /**
   * Control the HTML tag used for rendering the Divider.
   * @defaultValue 'div'
   */
  as?: 'hr' | 'div';
  /**
   * Indicate whether the Divider is used inside a Flex component to apply the right styling.
   * If set to false, make sure to have an explicit width/height style set on a parent HTML tag.
   * @defaultValue true
   */
  flexItem?: boolean;
  /**
   * The color of the Divider.
   * @defaultValue 'neutral'
   */
  color?: 'primary' | 'neutral' | 'success' | 'warning' | 'critical';
  /**
   * The visual style of the Divider.
   * @defaultValue 'default'
   */
  variant?: 'default' | 'accent';
}
// #endregion

/**
 * The `Divider` component visually separates groups of content.
 */
export const Divider = /* @__PURE__ */ forwardRef<
  HTMLDivElement | HTMLHRElement,
  DividerProps
>((props, ref) => {
  const {
    orientation = 'horizontal',
    flexItem = true,
    as = 'div',
    color = 'neutral',
    variant = 'default',
    'data-testid': dataTestId,
    className: consumerClassName,
    style: consumerStyle,
    ...remainingProps
  } = props;

  const DividerTag = as;

  return (
    <DividerTag
      role="separator"
      aria-orientation={orientation === 'vertical' ? orientation : undefined}
      // @ts-expect-error ref can't be div and hr here
      ref={ref}
      data-testid={dataTestId}
      className={clsx(
        dividerCSS({ orientation, flexItem, color, variant }),
        consumerClassName,
      )}
      style={consumerStyle}
      {...remainingProps}
    />
  );
});

(Divider as typeof Divider & { displayName: string }).displayName = 'Divider';
